input.new_string:
/** Buckets guarding the unauthenticated endpoints. */
const LOGIN_BUCKET = "auth:login";
const RESET_BUCKET = "auth:password-reset";

/**
 * Attempts are limited per address, ignoring letter case. Login and reset
 * stay on separate buckets so exhausting one never locks the other, and one
 * address never shares a counter with anyone else.
 */
function accountKey(email: string): OrgId {
  return email.toLowerCase() as OrgId;
}

/** A password-reset link is usable for 60 minutes after it is sent. */
const RESET_TTL_MS = 60 * 60 * 1000;

