export async function confirmPasswordReset(
  input: PasswordResetConfirmInput,
): Promise<User> {
  const tokenHash = hashToken(input.token);
  const stored = await resetTokenRepo.findResetTokenByHash(tokenHash);
  const owner = stored ? await userRepo.findUserById(stored.userId) : null;
  // Distinct from the request counter, so a full request budget does not
  // burn a link that was already sent, and one account cannot lock others.
  const subject = owner
    ? accountKey(`confirm:${owner.email}`)
    : (`confirm:${tokenHash}` as OrgId);
  const verdict = await consumeRateLimit(subject, RESET_BUCKET);
  if (!verdict.allowed) {
    throw new Error("Too many reset attempts; try again shortly");
  }

  const now = new Date().toISOString();
  if (!stored || stored.usedAt !== null || stored.expiresAt <= now) {
    throw new Error("That reset link is no longer valid");
  }

  const consumed = await resetTokenRepo.consumeResetToken(stored.id);
  if (!consumed) throw new Error("That reset link is no longer valid");

  await userRepo.updatePasswordHash(
    stored.userId,
    await hashPassword(input.password),
  );
  await sessionRepo.revokeSessionsForUser(stored.userId);

  const user = await userRepo.findUserById(stored.userId);
  if (!user) throw new Error("That reset link is no longer valid");

  return user;
}

