  userId: string;
  expiresAt: string;
  usedAt: string | null;
}): ResetToken {
  return {
    id: row.id,
    userId: brandId<UserId>(row.userId),
    expiresAt: toIsoTimestamp(row.expiresAt),
    usedAt: row.usedAt === null ? null : toIsoTimestamp(row.usedAt),
  };
}

/** Retires every still-unused link for this account and nobody else's. */
function retireUnusedResetTokens(userId: UserId): void {
  const stamp = toIsoTimestamp(new Date());
  getDb()
    .update(passwordResetTokens)
    .set({ usedAt: stamp, updatedAt: stamp })
    .where(
      and(
        eq(passwordResetTokens.userId, userId),
        isNull(passwordResetTokens.usedAt),
      ),
    )
    .run();
}

export async function issueResetToken(
  userId: UserId,
  tokenHash: string,
  expiresAt: IsoTimestamp,
): Promise<ResetToken> {
  retireUnusedResetTokens(userId);

  const stamp = toIsoTimestamp(new Date());
  const row = getDb()
    .insert(passwordResetTokens)
    .values({
      id: newId(),
      userId,
      tokenHash,
      expiresAt,
      usedAt: null,
      createdAt: stamp,
      updatedAt: stamp,
    })
    .returning()
    .get();

  return toResetToken(row);
}

/** Looks up a token whether or not it is still usable. */
export async function findResetTokenByHash(
  tokenHash: string,
): Promise<ResetToken | null> {
  const row = getDb()
    .select()
    .from(passwordResetTokens)
    .where(eq(passwordResetTokens.tokenHash, tokenHash))
    .get();

  return row ? toResetToken(row) : null;
}

/**
 * Returns the token only while it is unused and unexpired. A used link stays
 * used, and a later request for the same account retires the earlier one.
 */
export async function findLiveResetToken(
  tokenHash: string,
): Promise<ResetToken | null> {
  const row = getDb()
    .select()
    .from(passwordResetTokens)
    .where(
      and(
        eq(passwordResetTokens.tokenHash, tokenHash),
        isNull(passwordResetTokens.usedAt),
        gt(passwordResetTokens.expiresAt, new Date().toISOString()),
      ),
    )
    .get();

  return row ? toResetToken(row) : null;
}

/**
 * Single use. Returns false when the link was already consumed, so a replay
 * cannot change the password a second time.
 */
export async function consumeResetToken(id: string): Promise<boolean> {
  const stamp = toIsoTimestamp(new Date());
  const rows = getDb()
    .update(passwordResetTokens)
    .set({ usedAt: stamp, updatedAt: stamp })
    .where(and(eq(passwordResetTokens.id, id), isNull(passwordResetTokens.usedAt)))
    .returning({ id: passwordResetTokens.id })
    .all();
  return rows.length > 0;
}
