import { purgeExpiredSessions } from "@/server/repositories/session-repository";
import { findUserByEmail, insertUser } from "@/server/repositories/user-repository";
import { toIsoTimestamp } from "@/types/common";
import type { SessionId } from "@/types/common";

const sent: { to: string; html: string }[] = [];

vi.mock("@/server/services/email-service", () => ({
  renderEmail: async (_template: string, props: Record<string, unknown>) => ({
    subject: "reset",
    html: String(props.token ?? ""),
    text: String(props.expiresInMinutes ?? ""),
  }),
  sendEmail: async (message: { to: string; html: string }) => {
    sent.push({ to: message.to, html: message.html });
  },
}));

const PASSWORD = "CorrectHorse1Battery";
const NEXT = "NewPassword1Battery";
const DAY = 24 * 60 * 60 * 1000;

let cleanup: () => void;

async function user(email: string, password = PASSWORD) {
  return insertUser({
    email,
    name: email,
    passwordHash: await hashPassword(password),
  });
}

beforeAll(async () => {
  const dir = mkdtempSync(join(tmpdir(), "taskflow-auth-"));
  const path = join(dir, "taskflow.db");
  process.env.TASKFLOW_DB_PATH = path;
  await runMigrations(path);
  cleanup = () => rmSync(dir, { recursive: true, force: true });
  await user("a@example.com");
  await user("b@example.com");
});

afterAll(() => {
  cleanup?.();
});

beforeEach(() => {
  resetRateLimits();
  sent.length = 0;
});

describe("sessions", () => {
  it("signs out only the one session", async () => {
    const first = await login({ email: "a@example.com", password: PASSWORD, rememberMe: false });
    const second = await login({ email: "a@example.com", password: PASSWORD, rememberMe: false });
    const other = await login({ email: "b@example.com", password: PASSWORD, rememberMe: false });

    await destroySession(first.token);
    await destroySession("not-a-session");
    await destroySession(first.token);

    expect(await resolveSession(first.token)).toBeNull();
    expect(await resolveSession(second.token)).not.toBeNull();
    expect(await resolveSession(other.token)).not.toBeNull();

    const again = await login({ email: "a@example.com", password: PASSWORD, rememberMe: false });
    expect(await resolveSession(again.token)).not.toBeNull();

    const row = getDb()
      .select()
      .from(sessions)
      .where(eq(sessions.tokenHash, hashToken(second.token)))
      .get();
    expect(row).toBeTruthy();
    await logout(row!.id as SessionId);
    expect(await resolveSession(second.token)).toBeNull();
    expect(await resolveSession(other.token)).not.toBeNull();
    await logout(row!.id as SessionId);
  });

  it("honours remember me and refuses a session past its lifetime", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-04-01T00:00:00.000Z"));
    try {
      const short = await login({
        email: "a@example.com",
        password: PASSWORD,
        rememberMe: false,
      });
      const long = await login({
        email: "b@example.com",
        password: PASSWORD,
        rememberMe: true,
      });
      const shortPrincipal = await resolveSession(short.token);
      const longPrincipal = await resolveSession(long.token);
      expect(new Date(shortPrincipal!.expiresAt).getTime()).toBe(Date.parse("2026-04-02T00:00:00.000Z"));
      expect(new Date(longPrincipal!.expiresAt).getTime()).toBe(Date.parse("2026-05-01T00:00:00.000Z"));

      vi.setSystemTime(new Date("2026-04-01T23:59:59.999Z"));
      expect(await resolveSession(short.token)).not.toBeNull();

      vi.setSystemTime(new Date("2026-04-02T00:00:00.000Z"));
      expect(await resolveSession(short.token)).toBeNull();
      expect(await resolveSession(long.token)).not.toBeNull();

      const removed = await purgeExpiredSessions(toIsoTimestamp(new Date()));
      expect(removed).toBeGreaterThan(0);
      expect(await resolveSession(long.token)).not.toBeNull();

      vi.setSystemTime(new Date(Date.parse("2026-04-01T00:00:00.000Z") + 30 * DAY));
      expect(await resolveSession(long.token)).toBeNull();
    } finally {
      vi.useRealTimers();
    }
  });
});

describe("password reset", () => {
  it("issues a 60-minute single-use link and retires only that account's earlier links", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-06-01T00:00:00.000Z"));
    try {
      await requestPasswordReset({ email: "nobody@example.com" });
      expect(sent).toHaveLength(0);

      await requestPasswordReset({ email: "A@Example.com" });
      await requestPasswordReset({ email: "b@example.com" });
      const firstA = sent[0]!.html;
      const tokenB = sent[1]!.html;
      expect(sent[0]!.to).toBe("a@example.com");

      await requestPasswordReset({ email: "a@example.com" });
      const secondA = sent[2]!.html;
      expect(secondA).not.toBe(firstA);

      await expect(
        confirmPasswordReset({ token: firstA, password: NEXT, confirmPassword: NEXT }),
      ).rejects.toThrow(/no longer valid/i);

      vi.setSystemTime(new Date("2026-06-01T00:59:59.999Z"));
      const resetUser = await confirmPasswordReset({
        token: secondA,
        password: NEXT,
        confirmPassword: NEXT,
      });
      expect(resetUser.email).toBe("a@example.com");

      await expect(
        confirmPasswordReset({ token: secondA, password: NEXT, confirmPassword: NEXT }),
      ).rejects.toThrow(/no longer valid/i);

      await confirmPasswordReset({
        token: tokenB,
        password: NEXT,
        confirmPassword: NEXT,
      });

      const row = getDb()
        .select()
        .from(passwordResetTokens)
        .where(eq(passwordResetTokens.tokenHash, hashToken(secondA)))
        .get();
      expect(row?.expiresAt).toBe("2026-06-01T01:00:00.000Z");
    } finally {
      vi.useRealTimers();
    }
  });

  it("rejects an expired link and ends only that account's sessions", async () => {
    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date("2026-07-01T00:00:00.000Z"));
    try {
      const a1 = await login({ email: "a@example.com", password: NEXT, rememberMe: false });
      const a2 = await login({ email: "A@Example.com", password: NEXT, rememberMe: true });
      const b1 = await login({ email: "b@example.com", password: NEXT, rememberMe: false });

      await requestPasswordReset({ email: "a@example.com" });
      const token = sent.at(-1)!.html;

      vi.setSystemTime(new Date("2026-07-01T01:00:00.000Z"));
      await expect(
        confirmPasswordReset({ token, password: PASSWORD, confirmPassword: PASSWORD }),
      ).rejects.toThrow(/no longer valid/i);

      vi.setSystemTime(new Date("2026-07-01T00:30:00.000Z"));
      await requestPasswordReset({ email: "a@example.com" });
      const fresh = sent.at(-1)!.html;
      await confirmPasswordReset({
        token: fresh,
        password: PASSWORD,
        confirmPassword: PASSWORD,
      });

      expect(await resolveSession(a1.token)).toBeNull();
      expect(await resolveSession(a2.token)).toBeNull();
      expect(await resolveSession(b1.token)).not.toBeNull();

      await expect(
        login({ email: "a@example.com", password: NEXT, rememberMe: false }),
      ).rejects.toThrow(/credentials/i);
      const signedIn = await login({
        email: "A@Example.com",
        password: PASSWORD,
        rememberMe: false,
      });
      expect(signedIn.user.email).toBe("a@example.com");
    } finally {
      vi.useRealTimers();
    }
  });

  it("matches a mixed-case stored address", async () => {
    const stamp = new Date().toISOString();
    getDb()
      .insert(users)
      .values({
        id: "01HZZZMIXEDCASEUSER00000001",
        email: "Mixed@Example.com",
        name: "Mixed",
        passwordHash: await hashPassword(PASSWORD),
        timezone: "UTC",
        createdAt: stamp,
        updatedAt: stamp,
      })
      .run();
    const found = await findUserByEmail("mixed@example.com");
    expect(found?.email).toBe("Mixed@Example.com");
  });
});

describe("rate limits", () => {
  it("limits sign-in per address, including the right password, and still allows reset", async () => {
    await user("limit-a@example.com");
    await user("limit-b@example.com");
    const capacity = getBucketConfig("auth:login").capacity;

    for (let i = 0; i < capacity; i += 1) {
      const email = i % 2 === 0 ? "limit-a@example.com" : "LIMIT-A@example.com";
      await expect(
        login({ email, password: "wrong-password", rememberMe: false }),
      ).rejects.toThrow(/credentials/i);
    }

    await expect(
      login({ email: "limit-a@example.com", password: PASSWORD, rememberMe: false }),
    ).rejects.toThrow(/too many sign-in attempts/i);

    const other = await login({
      email: "limit-b@example.com",
      password: PASSWORD,
      rememberMe: false,
    });
    expect(other.user.email).toBe("limit-b@example.com");

    await requestPasswordReset({ email: "LIMIT-A@example.com" });
    expect(sent).toHaveLength(1);
    await confirmPasswordReset({
      token: sent[0]!.html,
      password: NEXT,
      confirmPassword: NEXT,
    });
  });

  it("limits reset requests per address without blocking another address or sign-in", async () => {
    await user("reset-a@example.com");
    await user("reset-b@example.com");
    const capacity = getBucketConfig("auth:password-reset").capacity;

    for (let i = 0; i < capacity; i += 1) {
      const email = i % 2 === 0 ? "reset-a@example.com" : "Reset-A@example.com";
      await requestPasswordReset({ email });
    }
    expect(sent).toHaveLength(capacity);
    const latest = sent.at(-1)!.html;

    await requestPasswordReset({ email: "reset-a@example.com" });
    expect(sent).toHaveLength(capacity);

    await requestPasswordReset({ email: "reset-b@example.com" });
    expect(sent).toHaveLength(capacity + 1);

    await confirmPasswordReset({
      token: latest,
      password: NEXT,
      confirmPassword: NEXT,
    });

    const signedIn = await login({
      email: "reset-a@example.com",
      password: NEXT,
      rememberMe: false,
    });
    expect(signedIn.token).toBeTruthy();
  });
});
